def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > budget:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return min(budget, 18.0)

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    units = supply / float(WATER_REQ)
    scarce = units < 2.0
    abundant = units >= 1.8

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if scarce:
        urgency += 1
    if desperate_opp >= 2:
        urgency += 1

    if budget <= DAILY_SALARY * 0.8:
        cap = budget
    elif urgency >= 5:
        cap = min(budget, DAILY_SALARY * 1.15)
    elif urgency >= 3:
        cap = min(budget, DAILY_SALARY * 0.95)
    else:
        cap = min(budget, DAILY_SALARY * 0.7)

    if urgency >= 5:
        bid = max(58.0, min(cap, max_prev * 0.72 + 4.0))
    elif urgency >= 3:
        anchor = max(42.0, min(60.0, avg_prev * 0.45 + 6.0))
        bid = min(cap, anchor)
    else:
        if max_prev >= 120:
            bid = 19.0 if abundant else 24.0
        elif max_prev >= 80:
            bid = 24.0 if abundant else 31.0
        else:
            bid = 28.0 if abundant else 36.0
        if rich_opp >= 2 and not abundant:
            bid += 4.0
        bid = min(cap, bid)

    if day >= 8:
        bid = min(budget, bid + 6.0)
    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, 63.0))

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60.0
    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], DAILY_SALARY * 1.2))
    if my_status['hp'] > 8:
        return float(min(my_status['budget'], avg_prev * 0.8))
    return float(min(my_status['budget'], avg_prev * 1.05))
